// A misspelt name must not report "all mutants killed" after running none.
const unknown = only.filter((n) => !MUTANTS.some(([name]) => name === n));
if (unknown.length) { console.error(`unknown mutant(s): ${unknown.join(', ')}`); process.exit(2); }
let survived = 0;
// Ctrl+C mid-mutant must not leave a mutated source behind.
let restore = null;
process.on('SIGINT', () => { restore?.(); process.exit(130); });
for (const [name, file, find, replace, testFile, pattern, tries = 1] of MUTANTS) {
  if (only.length && !only.includes(name)) continue;
  const path = join(ROOT, file);
  const original = readFileSync(path, 'utf8');
  if (!original.includes(find)) { console.log(`STALE    ${name}: pattern not found in ${file}`); survived++; continue; }
  restore = () => writeFileSync(path, original);
  writeFileSync(path, original.replace(find, replace));
  try {
    let killed = false;
    for (let i = 0; i < tries && !killed; i++) {
      const r = spawnSync(process.execPath, ['--test', '--test-name-pattern', pattern, join('tests', `${testFile}.test.mjs`)], { cwd: ROOT, encoding: 'utf8', timeout: 120000 });
      killed = r.status !== 0;
    }
    if (!killed) survived++;
    console.log(`${killed ? 'killed  ' : 'SURVIVED'} ${name}`);
  } finally {
    restore();
    restore = null;
  }
}
console.log(survived ? `${survived} mutant(s) survived` : 'all mutants killed');
process.exitCode = survived ? 1 : 0;
